const cursor=$('#cursor');const finePointer=matchMedia('(min-width: 761px) and (hover: hover) and (pointer: fine)');let cursorEnabled=false;function hideCursor(){cursor.style.opacity='0';document.body.classList.remove('custom-cursor');cursorEnabled=false}document.addEventListener('pointermove',e=>{if(!finePointer.matches||e.pointerType==='touch')return;const input=e.target.closest('input,textarea,select,dialog');if(input){hideCursor();return}document.body.classList.add('custom-cursor');cursorEnabled=true;cursor.style.opacity='1';cursor.style.transform=`translate3d(${e.clientX}px,${e.clientY}px,0)`;const target=e.target.closest('a,button');cursor.classList.toggle('is-link',!!target);cursor.querySelector('span').textContent=target?.dataset.cursor||(target?.classList.contains('close')?'CLOSE':target?.classList.contains('remove-zone')?'REMOVE':target?'SELECT':'')},{passive:true});document.documentElement.addEventListener('pointerleave',hideCursor);window.addEventListener('blur',hideCursor);document.addEventListener('keydown',e=>{if(e.key==='Tab')hideCursor()});finePointer.addEventListener('change',hideCursor);document.addEventListener('pointerdown',()=>cursor.classList.add('is-down'));document.addEventListener('pointerup',()=>cursor.classList.remove('is-down'));
