let soundEnabled=true;try{soundEnabled=localStorage.getItem('quiet-sound')!=='off'}catch{}let audioContext;let lastHover=0;function updateSoundButton(){const b=$('#sound');b.setAttribute('aria-pressed',String(soundEnabled));b.setAttribute('aria-label',soundEnabled?'Mute sound effects':'Enable sound effects');b.querySelector('span').textContent=soundEnabled?'Sound on':'Sound off'}
function initAudio(){if(!soundEnabled)return;try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume().catch(()=>{})}catch{}}
function playSound(kind){if(!soundEnabled||!audioContext||audioContext.state!=='running')return;$('#sound').dataset.audioState=audioContext.state;$('#sound').dataset.lastSound=kind;$('#sound').dataset.soundCount=String(Number($('#sound').dataset.soundCount||0)+1);const now=audioContext.currentTime;const duration=kind==='hover'?.027:.06;const buffer=audioContext.createBuffer(1,Math.ceil(audioContext.sampleRate*duration),audioContext.sampleRate);const data=buffer.getChannelData(0);for(let i=0;i<data.length;i++){const t=i/data.length;data[i]=(Math.random()*2-1)*Math.pow(1-t,5)}const noise=audioContext.createBufferSource();noise.buffer=buffer;const filter=audioContext.createBiquadFilter();filter.type='bandpass';filter.frequency.value=kind==='hover'?3400:1700;filter.Q.value=.6;const gain=audioContext.createGain();gain.gain.setValueAtTime(kind==='hover'?.11:.22,now);gain.gain.exponentialRampToValueAtTime(.001,now+duration);noise.connect(filter);filter.connect(gain);gain.connect(audioContext.destination);noise.start(now);noise.stop(now+duration);if(kind==='click'){const osc=audioContext.createOscillator();const tone=audioContext.createGain();osc.type='sine';osc.frequency.setValueAtTime(220,now);osc.frequency.exponentialRampToValueAtTime(90,now+.05);tone.gain.setValueAtTime(.07,now);tone.gain.exponentialRampToValueAtTime(.001,now+.05);osc.connect(tone);tone.connect(audioContext.destination);osc.start(now);osc.stop(now+.06)}}
document.addEventListener('pointerdown',initAudio,{capture:true});document.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' ')initAudio()},{capture:true});document.addEventListener('pointerover',e=>{const target=e.target.closest('a,button');if(!target||target.contains(e.relatedTarget))return;const now=performance.now();if(now-lastHover>80){playSound('hover');lastHover=now}});document.addEventListener('click',e=>{if(e.target.closest('a,button')&&!e.target.closest('#sound'))playSound('click')});$('#sound').onclick=()=>{soundEnabled=!soundEnabled;try{localStorage.setItem('quiet-sound',soundEnabled?'on':'off')}catch{}updateSoundButton();if(soundEnabled){initAudio();if(audioContext)audioContext.resume().then(()=>playSound('click')).catch(()=>{})}};updateSoundButton();
const sections=['work','about','contact'].map(id=>$('#'+id));const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){document.querySelectorAll('nav a').forEach(a=>{const active=a.getAttribute('href')==='#'+e.target.id;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}},{rootMargin:'-15% 0px -55% 0px'});sections.forEach(s=>observer.observe(s));
